#!/usr/bin/env python3
"""Build the local-only adult skills practice previews from content/skill_tools.json."""
import json
from pathlib import Path
from textwrap import dedent

ROOT = Path(__file__).resolve().parents[1]
DATA = json.loads((ROOT / "content" / "skill_tools.json").read_text())

BASE_CSS = dedent("""
  :root{--ink:#17212f;--muted:#586678;--line:#d7e0ea;--paper:#fff;--soft:#f3f6f9;--blue:#155e9f;--blue-deep:#173e68;--green:#176b51;--gold:#8a650a;--red:#b73a35;--shadow:0 16px 36px rgba(23,33,47,.09)}
  *{box-sizing:border-box}body{margin:0;background:#eef2f6;color:var(--ink);font:16px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}a{color:var(--blue)}button,input,select{font:inherit}.skip-link{position:absolute;left:-999px;top:8px;background:var(--ink);color:#fff;padding:8px 12px;z-index:10}.skip-link:focus{left:8px}
  .site-header{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:14px max(24px,calc((100% - 1180px)/2));background:#fff;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:10px;color:var(--ink);font-weight:850;text-decoration:none}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border-radius:8px;background:#222a33;color:#fff}.site-header nav{display:flex;gap:20px;flex-wrap:wrap}.site-header nav a{color:var(--ink);font-weight:700;text-decoration:none}.skill-main{max-width:1180px;margin:0 auto;padding:42px 24px 72px}.skill-hero{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(280px,.85fr);gap:28px;align-items:stretch}.skill-hero>div,.skill-card,.practice-panel,.rule-panel,.result-panel{background:var(--paper);border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow)}.skill-hero>div{padding:34px}.eyebrow{color:var(--green);font-size:.78rem;font-weight:850;letter-spacing:.08em;text-transform:uppercase}.skill-hero h1{font-size:clamp(2rem,5vw,4.6rem);line-height:.98;letter-spacing:-.05em;margin:12px 0 18px}.lede{font-size:1.12rem;color:var(--muted);max-width:58ch}.notice{margin:22px 0;padding:16px 18px;background:#fff8e9;border:1px solid #f0dda8;border-radius:8px}.skill-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;margin-top:24px}.skill-card{padding:24px}.skill-card h2{margin:8px 0}.skill-card p{color:var(--muted)}.button-row{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-top:18px}.primary,.secondary,.choice{border:1px solid var(--blue);border-radius:7px;padding:11px 15px;font-weight:800;cursor:pointer;text-decoration:none}.primary{background:var(--blue);color:#fff}.secondary{background:#fff;color:var(--blue)}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #f4c430;outline-offset:2px}.subtle{color:var(--muted);font-size:.92rem}.practice-layout{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(260px,.6fr);gap:22px}.practice-panel,.rule-panel,.result-panel{padding:24px}.practice-panel h1{margin:6px 0 8px;font-size:clamp(1.8rem,4vw,3.2rem);line-height:1.05}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:20px 0}.metric{padding:12px;background:var(--soft);border-radius:8px}.metric span,.metric strong{display:block}.metric span{color:var(--muted);font-size:.78rem;text-transform:uppercase;font-weight:800}.metric strong{font-size:1.35rem}.progress{height:10px;border-radius:99px;background:#e1e8ef;overflow:hidden}.progress i{display:block;height:100%;background:var(--green);transition:width .2s}.question-card{margin-top:24px;padding:20px;background:#f8fbfd;border:1px solid var(--line);border-radius:10px}.compare-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;align-items:center}.compare-cell{padding:16px;background:#fff;border:1px solid var(--line);border-radius:8px;font-weight:750;word-break:break-word}.compare-symbol{text-align:center;font-size:1.5rem;color:var(--muted)}.choice-grid{display:grid;gap:10px;margin-top:16px}.choice{text-align:left;background:#fff;color:var(--ink);border-color:var(--line);width:100%}.choice:hover,.choice:focus{border-color:var(--blue)}.choice.correct{border-color:var(--green);background:#edf8f2}.choice.wrong{border-color:var(--red);background:#fff0ef}.choice.neutral{border-color:var(--gold);background:#fff8e9}.feedback{margin-top:14px;padding:14px;border-left:4px solid var(--blue);background:#edf6fc}.timer-row{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:15px 0}.timer{font-variant-numeric:tabular-nums;font-size:1.6rem;font-weight:850}.timer.paused{color:var(--gold)}.switches{display:flex;flex-wrap:wrap;gap:14px}.switches label{display:flex;gap:7px;align-items:center}.session-note{padding:10px 12px;color:var(--muted);background:var(--soft);border-radius:8px}.rule-panel h2{margin-top:0}.rule-panel ul{padding-left:20px}.rule-panel code{background:var(--soft);padding:2px 5px;border-radius:4px}.table-wrap{overflow:auto}.records{width:100%;border-collapse:collapse;margin-top:14px}.records th,.records td{border:1px solid var(--line);padding:9px;text-align:left}.records th{background:var(--soft)}.result-panel{margin-top:22px}.error-list{display:grid;gap:8px;padding:0;list-style:none}.error-list li{padding:10px 12px;border-left:4px solid var(--red);background:#fff6f5}.print-only{display:none}.site-footer{max-width:1180px;margin:0 auto;padding:0 24px 38px;color:var(--muted)}
  @media(max-width:760px){.site-header{align-items:flex-start;flex-direction:column;padding:14px 18px}.site-header nav{gap:10px 14px}.skill-main{padding:24px 14px 48px}.skill-hero,.skill-grid,.practice-layout{grid-template-columns:1fr}.skill-hero>div,.skill-card,.practice-panel,.rule-panel,.result-panel{padding:20px}.metric-grid{grid-template-columns:repeat(2,1fr)}.compare-grid{grid-template-columns:1fr}.compare-symbol{display:none}.button-row>*{width:100%;text-align:center}.records{font-size:.9rem}}
  @media print{body{background:#fff}.site-header,.site-footer,.no-print,.rule-panel,.timer-row,.button-row,.notice{display:none!important}.skill-main{padding:0}.practice-layout{display:block}.practice-panel,.result-panel{box-shadow:none;border:0;padding:0}.print-only{display:block}.question-card{break-inside:avoid}}
""")

def shell(title, description, body, script="", canonical="skills-practice.html"):
    return dedent(f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title} | TestDayTools</title><meta name="description" content="{description}"><link rel="canonical" href="https://testdaytools.com/{canonical}"><style>{BASE_CSS}</style></head>
<body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="index.html" aria-label="TestDayTools home"><span class="brand-mark">T</span><span>TestDayTools</span></a><nav aria-label="Main navigation"><a href="skills-practice.html">Skills hub</a><a href="dmv-practice.html">DMV</a><a href="sat-tools.html">SAT</a><a href="ap-tools.html">AP</a></nav></header>
<main id="main" class="skill-main">{body}</main><footer class="site-footer">Original synthetic practice. No account, no real personal data, and progress stays in this browser. <a href="about.html">About TestDayTools</a></footer><script>{script}</script></body></html>''')

HUB_BODY = '''<section class="skill-hero"><div><p class="eyebrow">NEW PREVIEW · ADULT WORK SKILLS</p><h1>Practice speed and accuracy for everyday clerical work.</h1><p class="lede">Two small tools turn common office skills into short, explainable practice rounds: compare records carefully, then apply a filing rule you can read and verify.</p><div class="button-row"><a class="primary" href="clerical-checking-practice.html">Start clerical checking</a><a class="secondary" href="filing-practice.html">Try filing order</a></div></div><div><p class="eyebrow">Private by default</p><h2>Synthetic practice, not a test claim.</h2><p>Names, codes, and dates are generated for practice only. Nothing here uses real people or employer records, and results do not predict hiring outcomes.</p><ul><li>Keyboard-ready controls</li><li>Local results with clear reset</li><li>Visible rules and answer explanations</li></ul></div></section><div class="notice"><strong>Why these tools exist:</strong> clerical checking and filing tasks reward careful reading, explicit rules, and consistent decisions. The rules are visible so every result can be explained.</div><section class="skill-grid"><article class="skill-card"><p class="eyebrow">Tool A · Compare</p><h2>Clerical checking practice</h2><p>Compare synthetic names, numbers, and mixed codes. Mark match, mismatch, or unsure; then see false-match, false-mismatch, and omission patterns.</p><a class="primary" href="clerical-checking-practice.html">Open checking tool</a></article><article class="skill-card"><p class="eyebrow">Tool B · Order</p><h2>Filing order practice</h2><p>Choose which record comes first under an explicit name, alphanumeric, or date rule. Every question has a reproducible seed and independently checked answer.</p><a class="primary" href="filing-practice.html">Open filing tool</a></article></section>'''

CHECKING_BODY = '''<section class="practice-layout"><div class="practice-panel"><p class="eyebrow">TOOL A · COMPARE RECORDS</p><h1>Clerical checking practice</h1><p class="lede">Look at the two records, then decide whether they match exactly. Use “unsure” when you would flag a record for a second check.</p><div class="switches no-print"><label><input type="radio" name="mode" value="timed" checked> Timed · 90 seconds</label><label><input type="radio" name="mode" value="untimed"> Untimed</label></div><div class="timer-row no-print"><span class="timer" data-timer>01:30</span><button class="secondary" type="button" data-pause>Pause</button><button class="secondary" type="button" data-new>New round</button></div><div class="metric-grid" aria-live="polite"><div class="metric"><span>Completed</span><strong data-done>0 / 12</strong></div><div class="metric"><span>Correct</span><strong data-correct>0</strong></div><div class="metric"><span>Checks / min</span><strong data-rate>0.0</strong></div><div class="metric"><span>Accuracy</span><strong data-accuracy>—</strong></div></div><div class="progress" aria-label="Round progress"><i data-progress style="width:0%"></i></div><article class="question-card" data-question><p class="eyebrow">Record comparison <span data-qnum>1</span> of 12</p><div class="compare-grid"><div class="compare-cell" data-left></div><div class="compare-symbol" aria-hidden="true">↔</div><div class="compare-cell" data-right></div></div><div class="choice-grid no-print"><button class="choice" type="button" data-answer="match">Match exactly</button><button class="choice" type="button" data-answer="mismatch">Not a match</button><button class="choice" type="button" data-answer="unsure">Unsure / flag for review</button></div><div class="feedback" data-feedback hidden></div></article><div class="button-row no-print"><button class="primary" type="button" data-next disabled>Next comparison</button><button class="secondary" type="button" data-clear>Clear saved results</button></div></div><aside class="rule-panel"><h2>How to decide</h2><ul><li><strong>Match:</strong> every character, space, and digit is identical.</li><li><strong>Not a match:</strong> at least one visible character differs.</li><li><strong>Unsure:</strong> a deliberate omission flag; it is not counted as a correct decision.</li></ul><p class="subtle"><strong>Error definitions:</strong> false match = a mismatch marked as match; false mismatch = an exact match marked as mismatch; omission = Unsure.</p><p class="subtle">The round uses synthetic data generated from a visible seed. It does not reproduce an official exam or employer test.</p><div class="result-panel"><h2>Your local pattern</h2><p data-history>Not enough saved rounds yet.</p><ul class="error-list" data-errors></ul></div></aside></section>'''

FILING_BODY = '''<section class="practice-layout"><div class="practice-panel"><p class="eyebrow">TOOL B · APPLY A RULE</p><h1>Filing order practice</h1><p class="lede">Read the rule first. Then choose which record should be filed first. Each round is freshly generated but reproducible from its seed.</p><div class="switches no-print"><label>Rule <select data-rule><option value="name">Name · last, first, ID</option><option value="alpha">Alphanumeric · chunks left to right</option><option value="date">Date · earliest first</option></select></label><button class="secondary" type="button" data-new>New question</button></div><div class="metric-grid" aria-live="polite"><div class="metric"><span>Completed</span><strong data-done>0</strong></div><div class="metric"><span>Correct</span><strong data-correct>0</strong></div><div class="metric"><span>Accuracy</span><strong data-accuracy>—</strong></div><div class="metric"><span>Seed</span><strong data-seed>—</strong></div></div><article class="question-card" data-question><p class="eyebrow">Question <span data-qnum>1</span> · <span data-rule-label>Name rule</span></p><p><strong data-prompt>Which record should be filed first?</strong></p><div class="table-wrap"><table class="records"><thead><tr><th>Record</th><th>Value</th></tr></thead><tbody data-records></tbody></table></div><div class="choice-grid no-print" data-choices></div><div class="feedback" data-feedback hidden></div></article><div class="result-panel"><h2>Explain the decision</h2><p data-explanation>Choose an answer to see the comparison path and rule check.</p><ul class="error-list" data-errors></ul></div></div><aside class="rule-panel"><h2>Published rules</h2><div data-rule-help><h3>Name</h3><p>Compare last name A–Z, then first name A–Z, then record ID A–Z. Ignore case; do not reverse the displayed fields.</p></div><p class="subtle">Alphanumeric compares left-to-right chunks: letters A–Z, then numeric value 0–9. A shorter exact prefix comes first; if numeric values tie, the shorter digit chunk comes first (so A-2 precedes A-02), then record ID A–Z. Dates use ISO <code>YYYY-MM-DD</code>, earliest first, then record ID.</p><p class="subtle">Answer verification uses an independent comparator and a stored seed, not the selected option’s position.</p></aside></section>'''

CHECKING_JS = (ROOT / "content" / "clerical_checking.js").read_text()

FILING_JS = r'''(()=>{const KEY='tdt-skills-filing-v1';let seed=Date.now()%1000000,round=0,current=null,history=[];const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const rng=()=>{seed=(seed*1664525+1013904223)%4294967296;return seed/4294967296};const pick=a=>a[Math.floor(rng()*a.length)];const textCmp=(a,b)=>{a=a.toUpperCase();b=b.toUpperCase();return a<b?-1:a>b?1:0};const names=[['Bennett','Ari'],['Bennett','Zoe'],['Chandra','Mina'],['Diaz','Rafael'],['Ellis','Noah'],['Foster','Imani'],['Nguyen','Linh'],['Patel','Dev']];const dates=['2026-01-08','2025-12-19','2026-03-04','2025-11-27','2026-02-14','2026-01-29'];const codes=['A-2','A-10','A-11','B-3','B-12','C-4'];function alphaKey(v){return v.toUpperCase().split(/(\d+)/).filter(Boolean).map(x=>/^\d+$/.test(x)?[1,Number(x),x.length]:[0,x,0])}function compare(a,b,rule){if(rule==='name')return textCmp(a.last,b.last)||textCmp(a.first,b.first)||textCmp(a.id,b.id);if(rule==='date')return textCmp(a.date,b.date)||textCmp(a.id,b.id);let A=alphaKey(a.code),B=alphaKey(b.code);for(let i=0;i<Math.max(A.length,B.length);i++){if(!A[i])return -1;if(!B[i])return 1;if(A[i][0]!==B[i][0])return A[i][0]-B[i][0];if(A[i][1]!==B[i][1])return A[i][1]<B[i][1]?-1:1;if(A[i][0]===1&&A[i][2]!==B[i][2])return A[i][2]-B[i][2];}return textCmp(a.id,b.id)}function make(){let rule=$('[data-rule]').value,rows=[];for(let j=0;j<4;j++){if(rule==='name'){let n=pick(names);rows.push({last:n[0],first:n[1],id:`R-${Math.floor(rng()*90+10)}`})}else if(rule==='date')rows.push({date:pick(dates),id:`D-${Math.floor(rng()*90+10)}`});else rows.push({code:pick(codes),id:`C-${Math.floor(rng()*90+10)}`})}let seen=new Set;rows=rows.filter(r=>{let k=JSON.stringify(r);if(seen.has(k))return false;seen.add(k);return true});while(rows.length<4){if(rule==='name'){let n=names[rows.length];rows.push({last:n[0],first:n[1],id:`R-${rows.length+20}`})}else if(rule==='date')rows.push({date:dates[rows.length],id:`D-${rows.length+20}`});else rows.push({code:codes[rows.length],id:`C-${rows.length+20}`})}let sorted=[...rows].sort((a,b)=>compare(a,b,rule));let first=sorted[0];let correct=rows.indexOf(first);current={seed,rule,rows,correct,answered:null};render();save()}function label(rule){return rule==='name'?'Name · last, first, ID':rule==='date'?'Date · earliest first':'Alphanumeric · chunks left to right'}function display(r,rule){return rule==='name'?`${r.last}, ${r.first} · ${r.id}`:rule==='date'?`${r.date} · ${r.id}`:`${r.code} · ${r.id}`}function render(){if(!current)return;let rule=current.rule;$('[data-qnum]').textContent=round+1;$('[data-rule-label]').textContent=label(rule);$('[data-seed]').textContent=current.seed;$('[data-records]').innerHTML=current.rows.map((r,j)=>`<tr><th scope="row">${String.fromCharCode(65+j)}</th><td>${display(r,rule)}</td></tr>`).join('');$('[data-choices]').innerHTML=current.rows.map((r,j)=>`<button class="choice" type="button" data-choice="${j}" ${current.answered!==null?'disabled':''}>File ${String.fromCharCode(65+j)} first</button>`).join('');$$('[data-choice]').forEach(b=>b.addEventListener('click',()=>answer(Number(b.dataset.choice))));let f=$('[data-feedback]');f.hidden=current.answered===null;if(current.answered!==null){let ok=current.answered===current.correct;$$('[data-choice]').forEach(b=>b.classList.add(Number(b.dataset.choice)===current.correct?'correct':Number(b.dataset.choice)===current.answered?'wrong':''));f.innerHTML=`<strong>${ok?'Correct.':'Not quite.'}</strong> ${explain(rule,current.rows[current.correct],current.rows[current.answered])}`}$('[data-done]').textContent=history.length;$('[data-correct]').textContent=history.filter(x=>x.ok).length;$('[data-accuracy]').textContent=history.length?`${Math.round(history.filter(x=>x.ok).length/history.length*100)}%`:'—';$('[data-explanation]').textContent=current.answered===null?'Choose an answer to see the comparison path and rule check.':explain(rule,current.rows[current.correct],current.rows[current.answered]);$('[data-errors]').innerHTML=history.filter(x=>!x.ok).slice(-5).reverse().map(x=>`<li>${x.rule}: chose ${String.fromCharCode(65+x.chosen)}; correct was ${String.fromCharCode(65+x.correct)}.</li>`).join('')||'<li>No filing error recorded yet.</li>'}function explain(rule,good,bad){if(!bad)return'';if(rule==='name')return`The first record is ${display(good,rule)} because last name, then first name, then ID are compared A–Z. ${display(bad,rule)} comes later.`;if(rule==='date')return`${display(good,rule)} is earlier than ${display(bad,rule)} under ISO YYYY-MM-DD order, with record ID as a tie-break.`;return`${display(good,rule)} comes first under left-to-right alphanumeric chunks; compare letters before digits, then numeric value, fewer leading zeros, and record ID.`}function answer(n){if(current.answered!==null)return;current.answered=n;let ok=n===current.correct;history.push({ok,rule:current.rule,chosen:n,correct:current.correct});save();render()}function save(){localStorage.setItem(KEY,JSON.stringify({seed,round,current,history}))}function load(){let h=JSON.parse(localStorage.getItem(KEY)||'null');if(h){seed=h.seed;round=h.round;current=h.current;history=h.history||[];render()}else make()}$('[data-new]').addEventListener('click',()=>{round++;make()});$('[data-rule]').addEventListener('change',()=>{round++;make()});$('[data-print]').addEventListener('click',()=>{document.querySelector('[data-print-note]').textContent=`Seed ${current.seed} · rule ${label(current.rule)} · independent answer key included below.`;document.querySelector('[data-print-answer]').textContent=`Correct first record: ${String.fromCharCode(65+current.correct)} — ${display(current.rows[current.correct],current.rule)}. ${explain(current.rule,current.rows[current.correct],current.rows[(current.correct+1)%4])}`;window.print()});load()})();'''

FILING_JS = (ROOT / "content" / "filing_order.js").read_text()

def write(path, value):
    target = ROOT / path
    target.write_text(value)

def build():
    write("skills-practice.html", shell(DATA["hub"]["title"], DATA["hub"]["description"], HUB_BODY))
    checking = CHECKING_BODY.replace('data-left', 'id="left"').replace('data-right', 'id="right"').replace('data-pause', 'id="pause" data-pause')
    write("clerical-checking-practice.html", shell("Clerical checking practice", DATA["tools"][0]["description"], checking, CHECKING_JS, "clerical-checking-practice.html"))
    filing = FILING_BODY
    write("filing-practice.html", shell("Filing order practice", DATA["tools"][1]["description"], filing, FILING_JS, "filing-practice.html"))

if __name__ == "__main__":
    build()
    print("Built skills practice pages.")
